namespace {
constexpr uint8_t EXPANDER_ADDRESS = 0x20;
constexpr uint8_t OUTPUT_PORT_0 = 0x02;
constexpr uint8_t CONFIG_PORT_0 = 0x06;
constexpr uint8_t WIFI_LED = 1U << 4;
constexpr uint8_t ETH_LED = 1U << 5;
constexpr uint8_t STATUS_LED = 1U << 7;
constexpr uint8_t IDLE_OUTPUTS = WIFI_LED | ETH_LED;
constexpr uint32_t RETRY_MS = 1000;
constexpr int8_t SDA_PIN = 32, SCL_PIN = 33;
constexpr int8_t TX_ENABLE_1 = 4, TX_ENABLE_2 = 15;
// Use the second controller: these fixed board pins are reserved independently
// of WLED's optional, user-configurable Wire bus and cannot become LED outputs.
TwoWire boardWire(1);
bool boardPinsReady = false, boardBusReady = false, expanderReady = false;
bool boardStatusOn = false;
uint8_t lastOutputs = IDLE_OUTPUTS;
uint32_t lastRetry = 0, lastStatusChange = 0;

// The TCA9535/TCA9555 register pair auto-increments between its two ports.
bool writePorts(uint8_t reg, uint8_t port0, uint8_t port1) {
  boardWire.beginTransmission(EXPANDER_ADDRESS);
  boardWire.write(reg);
  boardWire.write(port0);
  boardWire.write(port1);
  return boardWire.endTransmission() == 0;
}

// Set latches before output directions to avoid pulses on MIO reset or Vout.
// P10 is port 1 bit 0 (linear bit 8), not linear bit 10. LOW holds MIO in reset.
bool initializeExpander() {
  if (!boardBusReady) boardBusReady = boardWire.begin(SDA_PIN, SCL_PIN, 100000);
  if (!boardBusReady) return false;
  if (!writePorts(OUTPUT_PORT_0, IDLE_OUTPUTS, 0)) return false;
  if (!writePorts(CONFIG_PORT_0, 0, 0xFE)) return false;
  lastOutputs = IDLE_OUTPUTS;
  return true;
}
}

// Claim fixed control pins before config readers can assign them to other roles.
void reserveWbMguPins() {
  const PinManagerPinType pins[] = {{TX_ENABLE_1, true}, {TX_ENABLE_2, true}, {SDA_PIN, true}, {SCL_PIN, true}};
  boardPinsReady = PinManager::allocateMultiplePins(pins, 4, PinOwner::BoardControl);
  if (!boardPinsReady) return;
  for (int8_t pin : {TX_ENABLE_1, TX_ENABLE_2}) {
    digitalWrite(pin, HIGH);
    pinMode(pin, OUTPUT);
  }
}

// Called after config parsing and before LED drivers start. Both RS-485 drivers
// stay enabled; terminators, failsafe bias, Vout and the internal MIO stay off.
void setupWbMgu() {
  if (!boardPinsReady) return;
  boardWire.setTimeOut(20);
  expanderReady = initializeExpander();
  lastRetry = millis();
}

// Update only changed LED bits and retry failed I2C transactions at most once/s.
// All board access stays on the main loop; no expander work runs per LED pixel.
void handleWbMgu() {
  if (!boardPinsReady) return;
  const uint32_t now = millis();
  if (!expanderReady) {
    if (now - lastRetry < RETRY_MS) return;
    lastRetry = now;
    expanderReady = initializeExpander();
    if (!expanderReady) return;
  }
  const uint32_t interval = Network.isConnected() ? 500 : apActive ? 1000 : 0;
  if (!interval) boardStatusOn = false;
  else if (now - lastStatusChange >= interval) {
    lastStatusChange = now;
    boardStatusOn = !boardStatusOn;
  }
  uint8_t outputs = IDLE_OUTPUTS;
  if (WiFi.status() == WL_CONNECTED || apActive) outputs &= ~WIFI_LED;
  if (ETH.linkUp()) outputs &= ~ETH_LED;
  if (boardStatusOn != getSauluxStatusInverted()) outputs |= STATUS_LED;
  if (outputs == lastOutputs) return;
  if (writePorts(OUTPUT_PORT_0, outputs, 0)) lastOutputs = outputs;
  else {
    expanderReady = false;
    lastRetry = now;
  }
}

// Report initialization health without performing I2C work in an HTTP callback.
void addWbMguInfo(JsonObject root) {
  JsonObject board = root.createNestedObject("wbMgu");
  board["expanderReady"] = expanderReady;
  board["controlPinsReady"] = boardPinsReady;
  board["expanderAddress"] = EXPANDER_ADDRESS;
  board["mioResetBit"] = 8;
}
